import java.awt.*;import java.awt.event.*;import java.sql.*;import java.util.*;import java.util.List;import javax.swing.*;import javax.swing.table.*;
public class CO4Solutions{
 static class FeeService{void pay(String id,double amount){if(id==null||id.isBlank())throw new IllegalArgumentException("Register number required");if(!Double.isFinite(amount)||amount<=0)throw new IllegalArgumentException("Amount must be positive");}}
 static class FeeWindow extends JFrame{JTextField id=new JTextField(12),amount=new JTextField(8);FeeWindow(){super("Fee Payment");setLayout(new FlowLayout());add(id);add(amount);JButton pay=new JButton("Pay"),clear=new JButton("Clear"),receipt=new JButton("Receipt");add(pay);add(clear);add(receipt);FeeService service=new FeeService();pay.addActionListener(e->{try{service.pay(id.getText(),Double.parseDouble(amount.getText()));JOptionPane.showMessageDialog(this,"Payment accepted");}catch(RuntimeException x){JOptionPane.showMessageDialog(this,x.getMessage());}});clear.addActionListener(e->{id.setText("");amount.setText("");});receipt.addActionListener(e->JOptionPane.showMessageDialog(this,"Receipt: "+id.getText()));setDefaultCloseOperation(DISPOSE_ON_CLOSE);pack();}}
 static class LibrarySearch extends JFrame{LibrarySearch(){super("Campus Library Search");setLayout(new BorderLayout());add(new JLabel("Library Search",SwingConstants.CENTER),BorderLayout.NORTH);JPanel search=new JPanel(new FlowLayout(FlowLayout.LEFT));JTextField q=new JTextField(20);JComboBox<String>cat=new JComboBox<>(new String[]{"Title","Author","Subject"});JButton go=new JButton("Search");search.add(q);search.add(cat);search.add(go);add(search,BorderLayout.PAGE_START);DefaultListModel<String>m=new DefaultListModel<>();add(new JScrollPane(new JList<>(m)),BorderLayout.CENTER);JPanel buttons=new JPanel();buttons.add(new JButton("Prev"));buttons.add(new JButton("Next"));buttons.add(new JButton("Reserve"));add(buttons,BorderLayout.SOUTH);JLabel status=new JLabel("Ready");add(status,BorderLayout.PAGE_END);go.addActionListener(e->{m.clear();m.addElement("Example result: "+q.getText());status.setText("1 result");});setSize(700,480);setDefaultCloseOperation(DISPOSE_ON_CLOSE);}}
 static class DrawPad extends JFrame{final List<Point>points=new ArrayList<>();final JLabel status=new JLabel("Clicks: 0");DrawPad(){super("Draw Pad");setLayout(new BorderLayout());add(status,BorderLayout.SOUTH);JPanel canvas=new JPanel(){protected void paintComponent(Graphics g){super.paintComponent(g);for(Point p:points)g.fillOval(p.x-3,p.y-3,6,6);}};canvas.setBackground(Color.WHITE);canvas.addMouseListener(new MouseAdapter(){@Override public void mouseClicked(MouseEvent e){points.add(e.getPoint());status.setText("Clicks: "+points.size());canvas.repaint();}});add(canvas,BorderLayout.CENTER);setSize(400,300);setDefaultCloseOperation(DISPOSE_ON_CLOSE);}}
 static class Converter extends JFrame{JTextField amount=new JTextField(10);JComboBox<String>target=new JComboBox<>(new String[]{"USD","EUR"});JLabel result=new JLabel(" ");Converter(){super("Currency Converter");setLayout(new FlowLayout());JButton b=new JButton("Convert");add(new JLabel("INR"));add(amount);add(target);add(b);add(result);ActionListener action=e->convert();b.addActionListener(action);amount.addActionListener(action);setDefaultCloseOperation(DISPOSE_ON_CLOSE);pack();}void convert(){try{double a=Double.parseDouble(amount.getText());if(!Double.isFinite(a)||a<0)throw new NumberFormatException();double rate=target.getSelectedItem().equals("USD")?.012:.011;String v=String.format(Locale.ROOT,"%.2f",a*rate);result.setText(v);JOptionPane.showMessageDialog(this,v);}catch(NumberFormatException e){result.setText("Invalid amount");JOptionPane.showMessageDialog(this,"Invalid amount");}}}
 record Registration(String student,String event){}
 static class RegistrationDao{final Connection c;RegistrationDao(Connection c){this.c=c;}void add(Registration r)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO registrations(student_id,event_name) VALUES(?,?)")){p.setString(1,r.student());p.setString(2,r.event());p.executeUpdate();}}List<Registration>page(int limit,int offset)throws SQLException{List<Registration>x=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT student_id,event_name FROM registrations ORDER BY student_id LIMIT ? OFFSET ?")){p.setInt(1,limit);p.setInt(2,offset);try(ResultSet r=p.executeQuery()){while(r.next())x.add(new Registration(r.getString(1),r.getString(2)));}}return x;}}
 static class EventApp extends JFrame{JTextField id=new JTextField(10);JComboBox<String>event=new JComboBox<>(new String[]{"Hackathon","Cultural Fest","Sports"});DefaultTableModel model=new DefaultTableModel(new String[]{"Student","Event"},0);EventApp(){super("Campus Event Registration");JPanel p=new JPanel();p.add(id);p.add(event);JButton add=new JButton("Register");p.add(add);add(p,BorderLayout.NORTH);add(new JScrollPane(new JTable(model)),BorderLayout.CENTER);JMenuBar bar=new JMenuBar();bar.add(new JMenu("File"));setJMenuBar(bar);add.addActionListener(e->{String s=id.getText().trim(),v=(String)event.getSelectedItem();if(s.isEmpty()){JOptionPane.showMessageDialog(this,"Student ID required");return;}for(int i=0;i<model.getRowCount();i++)if(s.equals(model.getValueAt(i,0))&&v.equals(model.getValueAt(i,1))){JOptionPane.showMessageDialog(this,"Duplicate registration");return;}model.addRow(new Object[]{s,v});});setSize(600,400);setDefaultCloseOperation(DISPOSE_ON_CLOSE);}}
 public static void main(String[]a){SwingUtilities.invokeLater(()->{String[]names={"Fee Window","Library Search","Draw Pad","Converter","Event Registration"};String c=(String)JOptionPane.showInputDialog(null,"Choose demo","CO4",JOptionPane.PLAIN_MESSAGE,null,names,names[0]);if(c==null)return;JFrame f=switch(c){case "Fee Window"->new FeeWindow();case "Library Search"->new LibrarySearch();case "Draw Pad"->new DrawPad();case "Converter"->new Converter();default->new EventApp();};f.setLocationRelativeTo(null);f.setVisible(true);});}
}